-- clear notes: Clear the notes of the returned loans
-- Changes exactly 2 Loan records of table loans: sets note to null, where status == "returned".
-- Dry run: psql -v ON_ERROR_STOP=1 -v last_modified_by_user_id=... -v last_modified_by_user_nameid=... -f clear-notes.sql
-- Apply: the same with -v apply=true. Without it every check runs against the data and the change is rolled back.
\set ON_ERROR_STOP on
\set QUIET on
\if :{?apply}
\else
\set apply false
\endif
\if :{?last_modified_by_user_id}
\else
DO $script$ BEGIN RAISE EXCEPTION 'clear-notes.sql: the variable last_modified_by_user_id is not set; give it as psql -v last_modified_by_user_id=<last_modified_by_user_id> (VARCHAR(255))'; END $script$;
\endif
\if :{?last_modified_by_user_nameid}
\else
DO $script$ BEGIN RAISE EXCEPTION 'clear-notes.sql: the variable last_modified_by_user_nameid is not set; give it as psql -v last_modified_by_user_nameid=<last_modified_by_user_nameid> (VARCHAR(255))'; END $script$;
\endif
BEGIN;
SET LOCAL specarch.apply = :'apply';
SET LOCAL specarch.last_modified_by_user_id = :'last_modified_by_user_id';
SET LOCAL specarch.last_modified_by_user_nameid = :'last_modified_by_user_nameid';
DO $script$
DECLARE
  found bigint;
  changed bigint;
BEGIN
  -- 1. Precondition: exactly 2 Loan records to change, locked until the end.
  SELECT count(*) INTO found FROM (SELECT 1 FROM loans WHERE (status = 'returned')
    AND is_deleted = false
    AND NOT (note IS NULL) FOR UPDATE) AS records;
  IF found <> 2 THEN
    RAISE EXCEPTION 'command clear notes: % Loan records hold status == "returned", not deleted, not already holding the values written, and the change expects exactly 2; nothing was changed', found;
  END IF;
  -- 2. The change, under the same condition.
  UPDATE loans
  SET note = NULL,
      last_modified_at = now(),
      last_modified_by_user_id = current_setting('specarch.last_modified_by_user_id', true)::VARCHAR,
      last_modified_by_user_nameid = current_setting('specarch.last_modified_by_user_nameid', true)::VARCHAR
  WHERE (status = 'returned')
    AND is_deleted = false
    AND NOT (note IS NULL);
  GET DIAGNOSTICS changed = ROW_COUNT;
  -- 3. Postcondition: the exact count.
  IF changed <> 2 THEN
    RAISE EXCEPTION 'command clear notes: the change wrote % Loan records, and exactly 2 was expected; another writer may have changed them after they were counted; nothing was changed', changed;
  END IF;
  -- 4. Dry run unless apply is true.
  IF current_setting('specarch.apply')::boolean THEN
    RAISE NOTICE 'command clear notes: 2 Loan records changed; committing';
  ELSE
    RAISE NOTICE 'command clear notes: dry run: 2 Loan records would change, and every check passed; rolling back. Run it again with -v apply=true to make the change';
  END IF;
END
$script$;
\if :apply
COMMIT;
\else
ROLLBACK;
\endif
